/// What others see of someone (design section 7, "Presence").
enum Presence {
  /// Not seen for 25 minutes, signed off, or invisible.
  offline('offline'),
  /// Using the app.
  online('online'),
  /// Set by hand, or idle for 10 minutes.
  away('away'),
  /// Not to be disturbed: their notifications are silenced.
  doNotDisturb('do_not_disturb');

  const Presence(this.json);

  /// Its JSON form.
  final String json;

  /// Reads [Presence] from its JSON form.
  static Presence fromJson(Object? v) => values.firstWhere((e) => e.json == v, orElse: () => throw FormatException('unknown Presence: $v'));
}

/// The presence you choose to show.
enum PresenceSetting {
  /// Shown online.
  online('online'),
  /// Shown away.
  away('away'),
  /// Shown as not to be disturbed; your own notifications are silenced.
  doNotDisturb('do_not_disturb'),
  /// Shown offline. Nothing is sent, but you still receive everything.
  invisible('invisible');

  const PresenceSetting(this.json);

  /// Its JSON form.
  final String json;

  /// Reads [PresenceSetting] from its JSON form.
  static PresenceSetting fromJson(Object? v) => values.firstWhere((e) => e.json == v, orElse: () => throw FormatException('unknown PresenceSetting: $v'));
}

