/// What to search messages for: everything given must match. See
/// [`Core::search`].
final class SearchQuery {
  const SearchQuery({
    this.text = '',
    this.conversation,
    this.from,
    this.hasLink = false,
    this.mentions,
    this.after,
    this.before,
    this.oldestFirst = false,
    required this.limit,
    this.offset = 0,
  });

  /// Reads [SearchQuery] from its JSON form.
  factory SearchQuery.fromJson(Map<String, Object?> j) => SearchQuery(
    text: switch (j['text']) { null => '', final v0 => v0 as String },
    conversation: j['conversation'] as String?,
    from: j['from'] as String?,
    hasLink: switch (j['has_link']) { null => false, final v0 => v0 as bool },
    mentions: j['mentions'] as String?,
    after: switch (j['after_ms']) { null => null, final v0 => DateTime.fromMillisecondsSinceEpoch(v0 as int) },
    before: switch (j['before_ms']) { null => null, final v0 => DateTime.fromMillisecondsSinceEpoch(v0 as int) },
    oldestFirst: switch (j['oldest_first']) { null => false, final v0 => v0 as bool },
    limit: j['limit'] as int,
    offset: switch (j['offset']) { null => 0, final v0 => v0 as int },
  );

  /// Words that must all appear, in any order, case or accents; each
  /// matches a word starting with it.
  final String text;

  /// Only in this conversation.
  final String? conversation;

  /// Only sent by this username.
  final String? from;

  /// Only messages with a link.
  final bool hasLink;

  /// Only messages that mention this username.
  final String? mentions;

  /// Only sent at or after this (Unix ms).
  final DateTime? after;

  /// Only sent before this (Unix ms).
  final DateTime? before;

  /// Oldest first, rather than newest.
  final bool oldestFirst;

  /// At most this many: the page size.
  final int limit;

  /// Skipping this many first: where the page starts.
  final int offset;

  /// Its JSON form.
  Map<String, Object?> toJson() => {
    'text': text,
    'conversation': conversation,
    'from': from,
    'has_link': hasLink,
    'mentions': mentions,
    'after_ms': after?.millisecondsSinceEpoch,
    'before_ms': before?.millisecondsSinceEpoch,
    'oldest_first': oldestFirst,
    'limit': limit,
    'offset': offset,
  };

  @override
  bool operator ==(Object other) => other is SearchQuery && other.text == text && other.conversation == conversation && other.from == from && other.hasLink == hasLink && other.mentions == mentions && other.after == after && other.before == before && other.oldestFirst == oldestFirst && other.limit == limit && other.offset == offset;

  @override
  int get hashCode => Object.hashAll([text, conversation, from, hasLink, mentions, after, before, oldestFirst, limit, offset]);
}

