  Map<String, Object?> toJson() => {
    'type': 'announcements_changed',
    'summary': summary.toJson(),
  };

  @override
  bool operator ==(Object other) => other is AnnouncementsChangedEvent && other.summary == summary;

  @override
  int get hashCode => Object.hashAll([summary]);
}

/// A subscriber fell behind and missed this many events: re-read what
/// it shows. The core never sends this itself; the daemon and the app's
/// bridge do, in place of what was missed.
final class LaggedEvent extends Event {
  const LaggedEvent({
    required this.missed,
  });

  /// Reads [LaggedEvent] from its JSON form.
  factory LaggedEvent.fromJson(Map<String, Object?> j) => LaggedEvent(
    missed: j['missed'] as int,
  );

  /// How many.
  final int missed;

  /// Its JSON form.
  @override
  Map<String, Object?> toJson() => {
    'type': 'lagged',
    'missed': missed,
  };

  @override
  bool operator ==(Object other) => other is LaggedEvent && other.missed == missed;

  @override
  int get hashCode => Object.hashAll([missed]);
}

/// Which picture: they differ in shape and size.
enum PictureKind {
  /// The round profile picture: square.
  avatar('avatar'),
  /// The banner across the top of a profile: three times as wide as tall.
  banner('banner');

  const PictureKind(this.json);

  /// Its JSON form.
  final String json;

  /// Reads [PictureKind] from its JSON form.
  static PictureKind fromJson(Object? v) => values.firstWhere((e) => e.json == v, orElse: () => throw FormatException('unknown PictureKind: $v'));
}

/// A colour, or a gradient between two, to fill something with.
///
/// Also a local API type (#[api]): its JSON form sits beside the wire form
/// and does not change it.
final class Fill {
  const Fill({
    required this.colors,
    required this.angle,
  });

  /// Reads [Fill] from its JSON form.
  factory Fill.fromJson(Map<String, Object?> j) => Fill(
    colors: (j['colors'] as List<Object?>).map((e0) => e0 as int).toList(),
    angle: j['angle'] as int,
  );

  /// One colour (solid), or two (a gradient from the first to the
  /// second), `0xRRGGBB` each.
  final List<int> colors;

  /// A gradient's direction, in degrees as in CSS: 0 runs from the bottom
  /// up, 90 left to right, 180 top to bottom. 0 for a solid colour.
  final int angle;

  /// Its JSON form.
  Map<String, Object?> toJson() => {
    'colors': colors,
    'angle': angle,
  };

  @override
  bool operator ==(Object other) => other is Fill && _deepEquals(other.colors, colors) && other.angle == angle;

  @override
  int get hashCode => Object.hashAll([_deepHash(colors), angle]);
}

/// How the client reaches the core: one call at a time, and the event stream.
abstract interface class PostTransport {
  /// Run [method] with [params] (JSON values); its result, a JSON value.
  Future<Object?> call(String method, Map<String, Object?> params);

  /// Live events, each a JSON object.
  Stream<Map<String, Object?>> get events;
}

/// The local API: what the app can ask of the core.
abstract interface class PostApi {
  /// Live events.
  Stream<Event> get events;

  /// Log out: this device removes itself from the account, then the
  /// profile closes. Refused on the account's only device, which would
  /// lose the account. Then delete the profile's files with
  /// [`delete_profile`].
  Future<void> logOut();

  /// The account on this device, if registered.
  Future<Identity?> identity();

  /// Create an account. `server` is a `wss://` URL.
  ///
  /// - [server]: The server's URL, `wss://…`.
  /// - [invite]: An invite code from one of the server's hosts.
  /// - [username]: 3 to 32 of a-z, 0-9 and _, starting with a letter.
  /// - [bot]: A bot account (the invite must be for one).
  Future<Identity> register({required String server, required String invite, required String username, bool bot = false});

  /// On a new device: offer it for linking to an existing account on
  /// `server`. Returns the code to enter on one of that account's devices;
  /// then call [`Core::finish_link`]. `bot` must match the account.
  ///
  /// - [server]: The account's server, `wss://…`.
  /// - [deviceName]: A name for this device, shown on the account's other devices.
  /// - [bot]: The account is a bot.
  Future<String> beginLink({required String server, required String deviceName, bool bot = false});

  /// On the new device: wait (up to ten minutes) for the code to be
  /// entered and approved, then log in and join the account's conversations.
  Future<Identity> finishLink();

  /// On an existing device: which device a link code would add.
  ///
  /// - [code]: The code the new device shows.
  Future<LinkRequest> linkInspect({required String code});

  /// On an existing device: add the device behind a link code to this
  /// account and to every conversation.
  ///
  /// - [code]: The code the new device shows.
  Future<LinkRequest> linkApprove({required String code});

  /// This account's devices, oldest first.
  Future<List<Device>> devices();

  /// Name one of this account's devices, given its ID or an unambiguous
  /// prefix. The name is shared only with the account's own devices.
  ///
  /// - [device]: The device's ID, or an unambiguous start of it.
  /// - [name]: Its new name.
  Future<void> renameDevice({required String device, required String name});

  /// Remove another of this account's devices, given its ID or an
  /// unambiguous prefix. It is cut off from the server and from every
  /// conversation; the account's contacts see that it was removed.
  ///
  /// - [device]: The device's ID, or an unambiguous start of it.
  Future<void> removeDevice({required String device});

  /// Whether both server connections are up.
  Future<bool> isConnected();

  /// Fetch and process everything new, and send what is queued.
  Future<void> sync();

  /// Tell a conversation's online members you are typing. Call it as you
  /// type; it sends at most once every three seconds.
  ///
  /// - [conversation]: Where you are typing.
  Future<void> sendTyping({required String conversation});

  /// Start a call in a conversation (design section 10), with this device
  /// in it. It rings `ring` (usernames); with nobody named, everyone in a
  /// DM or a group of up to eight, and nobody in a larger group, where the
  /// call shows to join. [`Event::CallChanged`] follows who joins.
  ///
  /// - [conversation]: Where.
  /// - [video]: A video call, rather than voice only.
  /// - [ring]: Who to ring (usernames); none for the usual choice.
  Future<CallJoin> startCall({required String conversation, bool video = false, List<String> ring = const <String>[]});

  /// Ring people (usernames) into a live call: members not in it yet.
  ///
  /// - [conversation]: The call's conversation.
  /// - [call]: The call.
  /// - [usernames]: Who to ring.
  Future<void> ringCall({required String conversation, required String call, required List<String> usernames});

  /// Join a live call from this device (answering it, if it is ringing).
  ///
  /// - [conversation]: The call's conversation.
  /// - [call]: The call.
  Future<CallJoin> joinCall({required String conversation, required String call});

  /// Leave a call this device is in. In a DM, this ends the call.
  ///
  /// - [conversation]: The call's conversation.
  /// - [call]: The call.
  Future<void> leaveCall({required String conversation, required String call});

  /// Decline a ringing call: the user's other devices stop ringing, and in
  /// a DM the caller hears no.
  ///
  /// - [conversation]: The call's conversation.
  /// - [call]: The call.
  Future<void> declineCall({required String conversation, required String call});

  /// The live calls, in every conversation.
  Future<List<Call>> calls();

  /// Choose the presence others see. Kept on this device; announced now
  /// and every ten minutes while listening, except when invisible.
  ///
  /// - [setting]: What to show.
  Future<void> setPresence({required PresenceSetting setting});

  /// The presence you chose on this device.
  Future<PresenceSetting> ownPresence();

  /// What this device last heard of someone's presence.
  ///
  /// - [username]: Whose.
  Future<Presence> presence({required String username});

  /// Open a DM with `username`, creating it if needed.
  ///
  /// - [username]: Who with.
  Future<Conversation> startDm({required String username});

  /// Create a named group with you as admin and these users as members.
  ///
  /// - [name]: The group's name.
  /// - [usernames]: Who else is in it.
  Future<Conversation> createGroup({required String name, required List<String> usernames});

  /// A conversation by ID.
  ///
  /// - [id]: Its ID.
  Future<Conversation> conversation({required String id});

  /// As an admin: add people to a group, with all their devices.
  ///
  /// - [conversation]: The group.
  /// - [usernames]: Who to add.
  Future<void> addMembers({required String conversation, required List<String> usernames});

  /// As an admin: remove people from a group, with all their devices.
  ///
  /// - [conversation]: The group.
  /// - [usernames]: Who to remove.
  Future<void> removeMembers({required String conversation, required List<String> usernames});

  /// As an admin: rename a group.
  ///
  /// - [conversation]: The group.
  /// - [name]: Its new name.
  Future<void> renameGroup({required String conversation, required String name});

  /// As an admin: make a member an admin, or stop them being one. A group
  /// always keeps at least one admin.
  ///
  /// - [conversation]: The group.
  /// - [username]: The member.
  /// - [admin]: True to make them an admin, false to remove the role.
  Future<void> setAdmin({required String conversation, required String username, required bool admin});

  /// As an admin: whether new members are shown past messages, and how many
  /// days back (0 means all of them).
  ///
  /// - [conversation]: The group.
  /// - [shared]: New members see past messages.
  /// - [days]: How many days back; 0 for all of them.
  Future<void> setHistory({required String conversation, required bool shared, required int days});

  /// Give this device fresh keys in every conversation now. This happens by
  /// itself weekly; doing it at once limits what a copy of the device's
  /// keys taken earlier can read from here on.
  Future<void> refreshKeys();

  /// Leave a group, with all your devices. It shows as left at once; the
  /// other members' devices complete the removal.
  ///
  /// - [conversation]: The group.
  Future<void> leaveGroup({required String conversation});

  /// The members of a conversation, by the name you see for them.
  ///
  /// - [conversation]: The conversation.
  Future<List<Member>> members({required String conversation});

  /// Live conversations, most recent first.
  Future<List<Conversation>> conversations();

  /// Mark a conversation read up to its newest message, on every one of
  /// this account's devices. Emits [`Event::ConversationChanged`] if its
  /// unread count changed.
  ///
  /// - [conversation]: The conversation.
  Future<void> markRead({required String conversation});

  /// Whether you send read receipts: on unless turned off. Delivery
  /// receipts always go.
  Future<bool> readReceipts();

  /// Turn read receipts on or off, on all your devices. Off, others do
  /// not see when you read their messages, and you do not see when they
  /// read yours.
  ///
  /// - [on]: Send them (the default), or not.
  Future<void> setReadReceipts({required bool on});

  /// Record that you compared safety numbers with `username` (or, with
  /// `false`, withdraw it). Shared with your other devices only.
  ///
  /// - [username]: Who with.
  /// - [verified]: True to mark them verified, false to withdraw it.
  Future<void> setVerified({required String username, required bool verified});

  /// An app setting on this device, such as the spellcheck language. Kept
  /// in the encrypted profile, since some (a personal dictionary) say
  /// something about what the user writes.
  ///
  /// - [key]: Its name: a-z, 0-9, `.`, `_` and `-`.
  Future<String?> setting({required String key});

  /// Set (or with `None` clear) an app setting on this device.
  ///
  /// - [key]: Its name: a-z, 0-9, `.`, `_` and `-`.
  /// - [value]: Its value; none clears it.
  Future<void> setSetting({required String key, String? value});

  /// The newest `limit` notices about a conversation, or with `None` about
  /// the account as a whole, oldest first. Notices are what
  /// [`Event::Notice`] announced, kept.
  ///
  /// - [conversation]: The conversation; none for the account's own notices.
  /// - [limit]: At most this many, the newest.
  Future<List<Notice>> notices({String? conversation, int limit = 50});

  /// The announcements channel at a glance: unread count, the newest,
  /// whether you are a host, and the maintenance plan.
  Future<Announcements> announcementSummary();

  /// The newest `limit` announcements, oldest first. They are kept for
  /// good: the server never deletes them, and neither does this device.
  ///
  /// - [limit]: At most this many, the newest.
  Future<List<Announcement>> announcements({int limit = 50});

  /// Mark every announcement read, on all your devices.
  Future<void> markAnnouncementsRead();

  /// Post an announcement to everyone on the server. Hosts only; needs a
  /// connection, and fails rather than waiting for one.
  ///
  /// - [text]: What to say.
  Future<void> announce({required String text});

  /// Plan maintenance (hosts only): everyone is told now unless `quiet`,
  /// reminded a day, an hour, 30 minutes and 5 minutes before, and told
  /// when it starts and when it is over.
  ///
  /// - [startsAt]: When it starts; none to start it now.
  /// - [minutes]: How long it should take.
  /// - [reason]: Why, shown to everyone; empty for no reason given.
  /// - [quiet]: Do not announce the plan now; the reminders still go out.
  Future<void> planMaintenance({DateTime? startsAt, required int minutes, String reason = '', bool quiet = false});

  /// Make a single-use invite code for someone to create an account with
  /// (hosts only), valid for `days` (1 to 30).
  ///
  /// - [bot]: For a bot account.
  /// - [days]: Days until it expires, 1 to 30.
  Future<Invite> createInvite({bool bot = false, int days = 7});

  /// Cancel the planned maintenance, or announce the one underway is over
  /// (hosts only).
  Future<void> endMaintenance();

  /// The newest `limit` messages of a conversation, oldest first.
  ///
  /// - [conversation]: The conversation.
  /// - [limit]: At most this many, the newest.
  Future<List<Message>> messages({required String conversation, int limit = 50});

  /// Messages matching `query`, from this device's search index: nothing
  /// is asked of the server. Each word matches a word starting with it,
  /// ignoring case and accents ("ecole" finds "École"). Deleted messages
  /// are never found, and an edited one is found by its latest text.
  /// Gives how many match in all, and the page asked for.
  ///
  /// - [query]: What to find.
  Future<SearchResults> search({required SearchQuery query});

  /// One message.
  ///
  /// - [conversation]: Its conversation.
  /// - [id]: The message.
  Future<Message> message({required String conversation, required String id});

  /// Who has one of your messages: each other member, and whether it is on
  /// one of their devices or read. Read shows only while you send read
  /// receipts yourself.
  ///
  /// - [conversation]: Its conversation.
  /// - [id]: The message: one of yours.
  Future<MessageReceipts> messageReceipts({required String conversation, required String id});

  /// Every version of a message, the original first.
  ///
  /// - [conversation]: Its conversation.
  /// - [id]: The message.
  Future<List<MessageVersion>> messageVersions({required String conversation, required String id});

  /// Send a text message.
  ///
  /// - [conversation]: Where.
  /// - [text]: The text.
  Future<Message> sendText({required String conversation, required String text});

  /// Edit one of your own messages. Every earlier version is kept.
  ///
  /// - [conversation]: Its conversation.
  /// - [id]: The message: one of yours.
  /// - [text]: The new text.
  Future<Message> editMessage({required String conversation, required String id, required String text});

  /// Delete one of your own messages, with all its versions, for everyone.
  ///
  /// - [conversation]: Its conversation.
  /// - [id]: The message: one of yours.
  Future<void> deleteMessage({required String conversation, required String id});

  /// Change your profile and share it with every conversation.
  ///
  /// - [update]: What to change; what is left out stays as it is.
  Future<void> setProfile({required ProfileUpdate update});

  /// Set your banner's colour or gradient, shown when you have no banner
  /// image, or clear it for the app's choice.
  ///
  /// - [fill]: The fill; none for the app's choice.
  Future<void> setBannerFill({Fill? fill});

  /// Set your profile colours, or clear them for the app's own look.
  ///
  /// - [theme]: The fill; none for the app's own look.
  Future<void> setTheme({Fill? theme});

  /// Set your profile picture or banner from an image file on this
  /// computer (PNG, JPEG, WebP or GIF; its middle is used, in shape), or
  /// remove it. As [`Core::set_picture`], for callers without the bytes
  /// in hand, such as bots.
  ///
  /// - [kind]: Which picture.
  /// - [path]: The image file; none removes the picture.
  Future<void> setPictureFile({required PictureKind kind, String? path});

  /// Write a picture this device has to a new file, by the ID a
  /// [`Person`] gives for it.
  ///
  /// - [id]: The picture's ID, from a person's `avatar` or `banner`.
  /// - [path]: Where to write it. It must not exist yet.
  Future<void> savePictureFile({required String id, required String path});

  /// Set (or clear, with an empty name) your display name in one conversation.
  ///
  /// - [conversation]: The conversation.
  /// - [name]: The name; empty clears it.
  Future<void> setConversationName({required String conversation, required String name});

  /// Set (or clear, with an empty name) a private nickname for someone.
  ///
  /// - [username]: Whose.
  /// - [nickname]: The nickname; empty clears it.
  Future<void> setNickname({required String username, required String nickname});

  /// What this device knows about a person.
  ///
  /// - [username]: Who.
  Future<Person> person({required String username});

  /// The safety number between you and `username`, as 12 groups of 5 digits.
  ///
  /// - [username]: Who with.
  Future<String> safetyNumber({required String username});
}

